        self.event_cache_size = self.parse_size(
            config.get("event_cache_size", _DEFAULT_EVENT_CACHE_SIZE)
        )
        self.cache_factors = {}
        cache_config = config.get("caches") or {}
        self.global_factor = cache_config.get(
            "global_factor", properties.default_factor_size
        )
        if not isinstance(self.global_factor, (int, float)):
            raise ConfigError("caches.global_factor must be a number.")
        properties.default_factor_size = self.global_factor
        individual_factors = cache_config.get("per_cache_factors") or {}
        if not isinstance(individual_factors, dict):
            raise ConfigError("caches.per_cache_factors must be a dictionary")
        individual_factors = {
            _canonicalise_cache_name(key): val
            for key, val in individual_factors.items()
        }
        individual_factors.update(
            {
                _canonicalise_cache_name(key[len(_CACHE_PREFIX) + 1 :]): float(val)
                for key, val in self._environ.items()
                if key.startswith(_CACHE_PREFIX + "_")
            }
        )
        for cache, factor in individual_factors.items():
            if not isinstance(factor, (int, float)):
                raise ConfigError(
                    "caches.per_cache_factors.%s must be a number" % (cache,)
                )
            self.cache_factors[cache] = factor
        self.resize_all_caches()
        properties.resize_all_caches_func = self.resize_all_caches
def load_module(provider: dict, config_path: Iterable[str]) -> Tuple[Type, Any]:
    """Loads a synapse module with its config
    Args:
        provider: a dict with keys 'module' (the module name) and 'config'
           (the config dict).
        config_path: the path within the config file. This will be used as a basis
           for any error message.
    Returns
        Tuple of (provider class, parsed config object)
    """
    modulename = provider.get("module")
    if not isinstance(modulename, str):
        raise ConfigError(
            "expected a string", path=itertools.chain(config_path, ("module",))
        )
    module, clz = modulename.rsplit(".", 1)
    module = importlib.import_module(module)
    provider_class = getattr(module, clz)
    module_config = provider.get("config") or {}
    try:
        provider_config = provider_class.parse_config(module_config)
    except jsonschema.ValidationError as e:
        raise json_error_to_config_error(e, itertools.chain(config_path, ("config",)))
    except ConfigError as e:
        raise _wrap_config_error(
            "Failed to parse config for module %r" % (modulename,),
            prefix=itertools.chain(config_path, ("config",)),
            e=e,
        )
    except Exception as e:
        raise ConfigError(
            "Failed to parse config for module %r" % (modulename,),
            path=itertools.chain(config_path, ("config",)),
        ) from e
    return provider_class, provider_config
def nested_logging_context(suffix: str) -> LoggingContext:
    """Creates a new logging context as a child of another.
    The nested logging context will have a 'name' made up of the parent context's
    name, plus the given suffix.
    CPU/db usage stats will be added to the parent context's on exit.
    Normal usage looks like:
        with nested_logging_context(suffix):
    Args:
        suffix: suffix to add to the parent context's 'name'.
    Returns:
        LoggingContext: new logging context.
    """
    curr_context = current_context()
    if not curr_context:
        logger.warning(
            "Starting nested logging context from sentinel context: metrics will be lost"
        )
        parent_context = None
    else:
        assert isinstance(curr_context, LoggingContext)
        parent_context = curr_context
    prefix = str(curr_context)
    return LoggingContext(
        prefix + "-" + suffix,
        parent_context=parent_context,
    )
def make_deferred_yieldable(deferred):
    """Given a deferred (or coroutine), make it follow the Synapse logcontext
    rules:
    If the deferred has completed (or is not actually a Deferred), essentially
    does nothing (just returns another completed deferred with the
    result/failure).
    If the deferred has not yet completed, resets the logcontext before
    returning a deferred. Then, when the deferred completes, restores the
    current logcontext before running callbacks/errbacks.
    (This is more-or-less the opposite operation to run_in_background.)
    """
    if inspect.isawaitable(deferred):
        deferred = defer.ensureDeferred(deferred)
    if not isinstance(deferred, defer.Deferred):
        return deferred
    if deferred.called and not deferred.paused:
        return deferred
    prev_context = set_current_context(SENTINEL_CONTEXT)
    deferred.addBoth(_set_context_cb, prev_context)
    return deferred

_WILDCARD_RUN = re.compile(r"([\?\*]+)")
def unwrapFirstError(failure):
    failure.trap(defer.FirstError)
    return failure.value.subFailure
def glob_to_regex(glob: str, word_boundary: bool = False) -> Pattern:
    """Converts a glob to a compiled regex object.
    Args:
        glob: pattern to match
        word_boundary: If True, the pattern will be allowed to match at word boundaries
           anywhere in the string. Otherwise, the pattern is anchored at the start and
           end of the string.
    Returns:
        compiled regex pattern
    """
    chunks = []
    for chunk in _WILDCARD_RUN.split(glob):
        if not _WILDCARD_RUN.match(chunk):
            chunks.append(re.escape(chunk))
            continue
        qmarks = chunk.count("?")
        if "*" in chunk:
            chunks.append(".{%d,}" % qmarks)
        else:
            chunks.append(".{%d}" % qmarks)
    res = "".join(chunks)
    if word_boundary:
        res = re_word_boundary(res)
    else:
        res = r"\A" + res + r"\Z"
    return re.compile(res, re.IGNORECASE)
def re_word_boundary(r: str) -> str:
    """
    Adds word boundary characters to the start and end of an
    expression to require that the match occur as a whole word,
    but do so respecting the fact that strings starting or ending
    with non-word characters will change word boundaries.
    """
    return r"(^|\W)%s(\W|$)" % (r,)
class PushRuleEvaluatorForEvent:
    def matches(
        self, condition: Dict[str, Any], user_id: str, display_name: str
    ) -> bool:
        if condition["kind"] == "event_match":
            return self._event_match(condition, user_id)
        elif condition["kind"] == "contains_display_name":
            return self._contains_display_name(display_name)
        elif condition["kind"] == "room_member_count":
            return _room_member_count(self._event, condition, self._room_member_count)
        elif condition["kind"] == "sender_notification_permission":
            return _sender_notification_permission(
                self._event, condition, self._sender_power_level, self._power_levels
            )
        else:
            return True
    def _event_match(self, condition: dict, user_id: str) -> bool:
        pattern = condition.get("pattern", None)
        if not pattern:
            pattern_type = condition.get("pattern_type", None)
            if pattern_type == "user_id":
                pattern = user_id
            elif pattern_type == "user_localpart":
                pattern = UserID.from_string(user_id).localpart
        if not pattern:
            logger.warning("event_match condition with no pattern")
            return False
        if condition["key"] == "content.body":
            body = self._event.content.get("body", None)
            if not body or not isinstance(body, str):
                return False
            return _glob_matches(pattern, body, word_boundary=True)
        else:
            haystack = self._get_value(condition["key"])
            if haystack is None:
                return False
            return _glob_matches(pattern, haystack)
    def _contains_display_name(self, display_name: str) -> bool:
        if not display_name:
            return False
        body = self._event.content.get("body", None)
        if not body or not isinstance(body, str):
            return False
        r = regex_cache.get((display_name, False, True), None)
        if not r:
            r1 = re.escape(display_name)
            r1 = re_word_boundary(r1)
            r = re.compile(r1, flags=re.IGNORECASE)
            regex_cache[(display_name, False, True)] = r
        return bool(r.search(body))
def _glob_matches(glob: str, value: str, word_boundary: bool = False) -> bool:
    """Tests if value matches glob.
    Args:
        glob
        value: String to test against glob.
        word_boundary: Whether to match against word boundaries or entire
            string. Defaults to False.
    """
    try:
        r = regex_cache.get((glob, True, word_boundary), None)
        if not r:
            r = glob_to_regex(glob, word_boundary)
            regex_cache[(glob, True, word_boundary)] = r
        return bool(r.search(value))
    except re.error:
        logger.warning("Failed to parse glob to regex: %r", glob)
        return False
