        if max_age is None:
            max_age = -1
        max_age = int(max_age)
        query_id = params.get("query_id", "adhoc")
        parameters = params.get(
            "parameters", collect_parameters_from_request(request.args)
        )
        parameterized_query = ParameterizedQuery(query, org=self.current_org)
