    def _observe_code(self, change):
        if self.reason == httputil.responses.get(change['old'], 'Unknown'):
            self.reason = httputil.responses.get(change['new'], 'Unknown')
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.code
