class StatusPage(Controller):
    def _data(self, days):
        """
        Return number of backups per days including failure.
        """
        def _key(d):
            return time.strftime(str(d).split('T')[0])
        base = RdiffTime().set_time(0, 0, 0) - datetime.timedelta(days=days)
        data = {_key(base + datetime.timedelta(days=i)): [] for i in range(0, days + 1)}
        success = {_key(base + datetime.timedelta(days=i)): 0 for i in range(0, days + 1)}
        failure = success.copy()
        for repo in self.app.currentuser.repo_objs:
            try:
                if len(repo.session_statistics):
                    for stat in repo.session_statistics[base:]:
                        key = _key(stat.date)
                        if key not in success:
                            continue
                        success[key] = success.get(key, 0) + 1
                        data[key].append(stat)
                        if stat.errors:
                            failure[key] += 1
            except Exception:
                logger.warning('failure to read session statistics from %s', repo, exc_info=1)
        return {
            'backup_count': [
                {'name': _('Successful Backup'), 'data': success},
                {'name': _('Backup with errors'), 'data': failure},
            ],
            'data': data,
        }
class UserObject(Base):
    userid = Column('UserID', Integer, primary_key=True)
    def add_access_token(self, name, expiration_time=None, length=16):
        """
        Create a new access token. Return the un-encrypted value of the token.
        """
        assert name
        assert length >= 8
        token = ''.join(secrets.choice(string.ascii_lowercase) for i in range(length))
        try:
            obj = Token(userid=self.userid, name=name, hash_token=hash_password(token), expiration_time=expiration_time)
            obj.add()
        except IntegrityError:
            Token.session.rollback()
            raise ValueError(_("Duplicate token name: %s") % name)
        cherrypy.engine.publish('access_token_added', self, name)
        return token
    def delete(self, *args, **kwargs):
        cfg = cherrypy.tree.apps[''].cfg
        if self.username == cfg.admin_user:
            raise ValueError(_("can't delete admin user"))
        SshKey.query.filter(SshKey.userid == self.userid).delete()
        RepoObject.query.filter(RepoObject.userid == self.userid).delete()
        Token.query.filter(Token.userid == self.userid).delete()
        Base.delete(self)
