class EnhancedPaginator(Paginator):
    def __init__(self, object_list, per_page, **kwargs):
        try:
            per_page = int(per_page)
            if per_page < 1:
                per_page = get_settings_or_config("PAGINATE_COUNT")
        except ValueError:
            per_page = get_settings_or_config("PAGINATE_COUNT")
        max_page_size = get_settings_or_config("MAX_PAGE_SIZE")
        if max_page_size:
            per_page = min(per_page, max_page_size)
        super().__init__(object_list, per_page, **kwargs)
def get_paginate_count(request):
    """
    Determine the length of a page, using the following in order:
        1. per_page URL query parameter
        2. Saved user preference
        3. PAGINATE_COUNT global setting.
    """
    if "per_page" in request.GET:
        try:
            per_page = int(request.GET.get("per_page"))
            if request.user.is_authenticated:
                request.user.set_config("pagination.per_page", per_page, commit=True)
            return per_page
        except ValueError:
            pass
    if request.user.is_authenticated:
        return request.user.get_config("pagination.per_page", get_settings_or_config("PAGINATE_COUNT"))
    return get_settings_or_config("PAGINATE_COUNT")
