            user = User.query.filter(User.username == username).first()
            if user is not None:
                return jsonify({"error": "User already exists."}), 409
            user = User(
                username=username,
                password_hash=generate_password_hash(password),
                uuid=str(uuid.uuid4()),
            )
            db.session.add(user)
            db.session.commit()
            return ""
        else:
            return jsonify({"error": "No username supplied."}), 400
