                    "with",
                    "_sz",
                    ["add", 32, ["mload", "_source"]],
                    ["assert", ["call", ["gas"], 4, 0, "_source", "_sz", destination, "_sz"]],
                ],
            ],
            typ=None,
            add_gas_estimate=_identity_gas_bound(source.typ.maxlen),
            annotation="Memory copy",
