                    if img_orig is not None and img_orig.shape is not None:
                        if any((settings.hflip, settings.vflip, settings.rotation)):
                            if settings.hflip and settings.vflip:
                                img_edited = cv2.flip(img_orig, -1)
                            elif settings.hflip:
