def encode_int(n):
    """
    Encodes an int as a variable length signed 29-bit integer as defined by
    the spec.
    @param n: The integer to be encoded
    @return: The encoded string
    @rtype: C{str}
    @raise OverflowError: C{c} is out of range.
    """
    global ENCODED_INT_CACHE
    try:
        return ENCODED_INT_CACHE[n]
    except KeyError:
        pass
    if n < MIN_29B_INT or n > MAX_29B_INT:
        raise OverflowError("Out of range")
    if n < 0:
        n += 0x20000000
    bytes = ''
    real_value = None
    if n > 0x1fffff:
        real_value = n
        n >>= 1
        bytes += chr(0x80 | ((n >> 21) & 0xff))
    if n > 0x3fff:
        bytes += chr(0x80 | ((n >> 14) & 0xff))
    if n > 0x7f:
        bytes += chr(0x80 | ((n >> 7) & 0xff))
    if real_value is not None:
        n = real_value
    if n > 0x1fffff:
        bytes += chr(n & 0xff)
    else:
        bytes += chr(n & 0x7f)
    ENCODED_INT_CACHE[n] = bytes
    return bytes
class Decoder(codec.Decoder):
    def readLongString(self):
        """
        Read UTF8 string.
        """
        l = self.stream.read_ulong()
        bytes = self.stream.read(l)
        return self.context.getStringForBytes(bytes)
    def readXML(self):
        """
        Read XML.
        """
        data = self.readLongString()
        root = xml.fromstring(
            data,
            forbid_dtd=self.context.forbid_dtd,
            forbid_entities=self.context.forbid_entities,
        )
        self.context.addObject(root)
        return root

class ArchiveFile:
    def file_properties(self) -> Dict[str, Any]:
        """Return file properties as a hash object. Following keys are included: ‘readonly’, ‘is_directory’,
        ‘posix_mode’, ‘archivable’, ‘emptystream’, ‘filename’, ‘creationtime’, ‘lastaccesstime’,
        ‘lastwritetime’, ‘attributes’
        """
        properties = self._file_info
        if properties is not None:
            properties["readonly"] = self.readonly
            properties["posix_mode"] = self.posix_mode
            properties["archivable"] = self.archivable
            properties["is_directory"] = self.is_directory
        return properties
    def _get_unix_extension(self) -> Optional[int]:
        attributes = self._get_property("attributes")
