                self.volstate[vol.vpath] = "busy (hashing files)"
                _, vac = self._build_file_index(vol, list(all_vols.values()))
                if vac:
                    need_vac[vol] = True
            if "e2v" in vol.flags:
                t = "online (integrity-check pending)"
