    def shutdown(self) -> None:
        if self.stopping:
            return
        self.stopping = True
        self.stop_req = True
        with self.stop_cond:
            self.stop_cond.notify_all()
        ret = 1
        try:
            self.pr("OPYTHAT")
            slp = 0.0
            if self.mdns:
                Daemon(self.mdns.stop)
                slp = time.time() + 0.5
            if self.ssdp:
                Daemon(self.ssdp.stop)
                slp = time.time() + 0.5
            self.broker.shutdown()
            self.tcpsrv.shutdown()
            self.up2k.shutdown()
            if self.thumbsrv:
                self.thumbsrv.shutdown()
                for n in range(200):
                    time.sleep(0.05)
                    if self.thumbsrv.stopped():
                        break
                    if n == 3:
                        self.pr("waiting for thumbsrv (10sec)...")
            if hasattr(self, "smbd"):
                slp = max(slp, time.time() + 0.5)
                Daemon(self.kill9, a=(1,))
                Daemon(self.smbd.stop)
            while time.time() < slp:
                time.sleep(0.1)
            self.pr("nailed it", end="")
            ret = self.retcode
        except:
            self.pr("\033[31m[ error during shutdown ]\n{}\033[0m".format(min_ex()))
            raise
        finally:
            if self.args.wintitle:
                print("\033]0;\033\\", file=sys.stderr, end="")
                sys.stderr.flush()
            self.pr("\033[0m")
            if self.logf:
                self.logf.close()
            self.stopped = True
            sys.exit(ret)
