        try:
            if not start:
                start, end = max(0, maxlen-int(end)), maxlen
            elif not end:
                start, end = int(start), maxlen
            else:
                start, end = int(start), min(int(end)+1, maxlen)
            if 0 <= start < end <= maxlen:
                yield start, end
        except ValueError:
            pass
