    if isinstance(orig_data, basestring):
        sub_list = [('{%','{
        if from_remote or (from_inventory and '{{' in data and LOOKUP_REGEX.search(data)):
            sub_list.extend([('{{','{
        for pattern,replacement in sub_list:
            data = data.replace(pattern, replacement)
