def make_return_stmt(ir_val: IRnode, stmt: Any, context: Context) -> Optional[IRnode]:
    sig = context.sig
    jump_to_exit = ["exit_to", f"_sym_{sig.exit_sequence_label}"]
    if context.return_type is None:
        if stmt.value is not None:
            return None
    else:
        check_assign(dummy_node_for_type(context.return_type), ir_val)
    def finalize(fill_return_buffer):
        fill_return_buffer = IRnode.from_list(
            fill_return_buffer, annotation=f"fill return buffer {sig._ir_identifier}"
        )
        cleanup_loops = "cleanup_repeat" if context.forvars else "seq"
        return IRnode.from_list(["seq", fill_return_buffer, cleanup_loops, jump_to_exit])
    if context.return_type is None:
        jump_to_exit += ["return_pc"]
        return finalize(["seq"])
    if context.is_internal:
        dst = IRnode.from_list(["return_buffer"], typ=context.return_type, location=MEMORY)
        fill_return_buffer = make_setter(dst, ir_val)
        jump_to_exit += ["return_pc"]
        return finalize(fill_return_buffer)
    else:
        external_return_type = calculate_type_for_external_return(context.return_type)
        maxlen = external_return_type.abi_type.size_bound()
        can_skip_encode = (
            abi_encoding_matches_vyper(ir_val.typ)
            and ir_val.location == MEMORY
            and not needs_clamp(ir_val.typ, ir_val.encoding)
        )
        if can_skip_encode:
            assert ir_val.typ.memory_bytes_required == maxlen
            jump_to_exit += [ir_val, maxlen]
            return finalize(["pass"])
        ir_val = wrap_value_for_external_return(ir_val)
        return_buffer_ofst = context.new_internal_variable(get_type_for_exact_size(maxlen))
        return_len = abi_encode(return_buffer_ofst, ir_val, context, returns_len=True, bufsz=maxlen)
        jump_to_exit += [return_buffer_ofst, return_len]
        return finalize(["pass"])
def ir_for_self_call(stmt_expr, context):
    from vyper.codegen.expr import Expr
    method_name = stmt_expr.func.attr
    pos_args_ir = [Expr(x, context).ir_node for x in stmt_expr.args]
    sig, kw_vals = context.lookup_internal_function(method_name, pos_args_ir, stmt_expr)
    kw_args_ir = [Expr(x, context).ir_node for x in kw_vals]
    args_ir = pos_args_ir + kw_args_ir
    args_tuple_t = TupleT([x.typ for x in args_ir])
    args_as_tuple = IRnode.from_list(["multi"] + [x for x in args_ir], typ=args_tuple_t)
    if context.is_constant() and sig.mutability not in ("view", "pure"):
        raise StateAccessViolation(
            f"May not call state modifying function "
            f"'{method_name}' within {context.pp_constancy()}.",
            stmt_expr,
        )
    if not sig.internal:
        raise StructureException("Cannot call external functions via 'self'", stmt_expr)
    return_label = _generate_label(f"{sig.internal_function_label}_call")
    if sig.return_type is not None:
        return_buffer = IRnode.from_list(
            context.new_internal_variable(sig.return_type), annotation=f"{return_label}_return_buf"
        )
    else:
        return_buffer = None
    dst_tuple_t = TupleT([arg.typ for arg in sig.args])
    args_dst = IRnode(sig.frame_info.frame_start, typ=dst_tuple_t, location=MEMORY)
    if args_as_tuple.contains_self_call:
        copy_args = ["seq"]
        tmp_args_buf = IRnode(
            context.new_internal_variable(dst_tuple_t), typ=dst_tuple_t, location=MEMORY
        )
        copy_args.append(
            make_setter(tmp_args_buf, args_as_tuple)
        )
        copy_args.append(make_setter(args_dst, tmp_args_buf))
    else:
        copy_args = make_setter(args_dst, args_as_tuple)
    goto_op = ["goto", sig.internal_function_label]
    if return_buffer is not None:
        goto_op += [return_buffer]
    goto_op += [push_label_to_stack(return_label)]
    call_sequence = ["seq"]
    call_sequence.append(eval_once_check(_freshname(stmt_expr.node_source_code)))
    call_sequence.extend([copy_args, goto_op, ["label", return_label, ["var_list"], "pass"]])
    if return_buffer is not None:
        call_sequence += [return_buffer]
    o = IRnode.from_list(
        call_sequence,
        typ=sig.return_type,
        location=MEMORY,
        annotation=stmt_expr.get("node_source_code"),
        add_gas_estimate=sig.gas_estimate,
    )
    o.is_self_call = True
    return o
def _unpack_returndata(buf, fn_type, call_kwargs, contract_address, context, expr):
    return_t = fn_type.return_type
    if return_t is None:
        return ["pass"], 0, 0
    wrapped_return_t = calculate_type_for_external_return(return_t)
    abi_return_t = wrapped_return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    encoding = Encoding.ABI
    buf = IRnode.from_list(
        buf,
        typ=wrapped_return_t,
        location=MEMORY,
        encoding=encoding,
        annotation=f"{expr.node_source_code} returndata buffer",
    )
    unpacker = ["seq"]
    if not call_kwargs.skip_contract_check:
        assertion = IRnode.from_list(
            ["assert", ["ge", "returndatasize", min_return_size]],
            error_msg="returndatasize too small",
        )
        unpacker.append(assertion)
    assert isinstance(wrapped_return_t, TupleT)
    if needs_clamp(wrapped_return_t, encoding):
        return_buf = context.new_internal_variable(wrapped_return_t)
        return_buf = IRnode.from_list(return_buf, typ=wrapped_return_t, location=MEMORY)
        unpacker.append(make_setter(return_buf, buf))
    else:
        return_buf = buf
    if call_kwargs.default_return_value is not None:
        override_value = wrap_value_for_external_return(call_kwargs.default_return_value)
        stomp_return_buffer = ["seq"]
        if not call_kwargs.skip_contract_check:
            stomp_return_buffer.append(_extcodesize_check(contract_address))
        stomp_return_buffer.append(make_setter(return_buf, override_value))
        unpacker = ["if", ["eq", "returndatasize", 0], stomp_return_buffer, unpacker]
    unpacker = ["seq", unpacker, return_buf]
    return unpacker, ret_ofst, ret_len
def _external_call_helper(contract_address, args_ir, call_kwargs, call_expr, context):
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    ret.append(eval_once_check(_freshname(call_expr.node_source_code)))
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
