def signup(request):
    if not settings.REGISTRATION_OPEN:
        return HttpResponseForbidden()
    ctx = {}
    form = forms.SignupForm(request.POST)
    if form.is_valid():
        email = form.cleaned_data["identity"]
        if not User.objects.filter(email=email).exists():
            tz = form.cleaned_data["tz"]
            user = _make_user(email, tz)
            profile = Profile.objects.for_user(user)
            profile.send_instant_login_link()
    else:
        ctx = {"form": form}
    response = render(request, "accounts/signup_result.html", ctx)
    if "form" not in ctx:
        response.set_cookie("auto-login", "1", max_age=300, httponly=True)
    return response
def check_token(request, username, token, new_email=None):
    if request.user.is_authenticated:
        auth_logout(request)
    if request.method != "POST" and "auto-login" not in request.COOKIES:
        return render(request, "accounts/check_token_submit.html")
    user = authenticate(username=username, token=token)
    if user is not None and user.is_active:
        if new_email:
            if User.objects.filter(email=new_email).exists():
                request.session["bad_link"] = True
                return redirect("hc-login")
            user.email = new_email
            user.set_unusable_password()
            user.save()
        user.profile.token = ""
        user.profile.save()
        return _check_2fa(request, user)
    request.session["bad_link"] = True
    return redirect("hc-login")
def change_email_verify(request, signed_payload):
    try:
        payload = TimestampSigner().unsign_object(signed_payload, max_age=900)
    except BadSignature:
        return render(request, "bad_link.html")
    return check_token(request, payload["u"], payload["t"], payload["e"])
def login_webauthn(request):
    if not settings.RP_ID:
        return HttpResponse(status=500)
    if request.user.is_authenticated:
        return HttpResponseBadRequest()
    if "2fa_user" not in request.session:
        return HttpResponseBadRequest()
    user_id, email, timestamp = request.session["2fa_user"]
    if timestamp + 300 < time.time():
        return redirect("hc-login")
    try:
        user = User.objects.get(id=user_id, email=email)
    except User.DoesNotExist:
        return HttpResponseBadRequest()
    credentials = user.credentials.values_list("data", flat=True)
    helper = GetHelper(settings.RP_ID, credentials)
    if request.method == "POST":
        form = forms.WebAuthnForm(request.POST)
        if not form.is_valid():
            return HttpResponseBadRequest()
        if not helper.verify(request.session["state"], form.cleaned_data["response"]):
            return HttpResponseBadRequest()
        request.session.pop("state")
        request.session.pop("2fa_user")
        auth_login(request, user, "hc.accounts.backends.EmailBackend")
        return _redirect_after_login(request)
    options, request.session["state"] = helper.prepare()
    totp_url = None
    if user.profile.totp:
        totp_url = reverse("hc-login-totp")
        redirect_url = request.GET.get("next")
        if _allow_redirect(redirect_url):
            totp_url += "?next=%s" % redirect_url
    ctx = {
        "options": options,
        "totp_url": totp_url,
    }
    return render(request, "accounts/login_webauthn.html", ctx)
def login_totp(request):
    if request.user.is_authenticated:
        return HttpResponseBadRequest()
    if "2fa_user" not in request.session:
        return HttpResponseBadRequest()
    user_id, email, timestamp = request.session["2fa_user"]
    if timestamp + 300 < time.time():
        return redirect("hc-login")
    try:
        user = User.objects.get(id=user_id, email=email)
    except User.DoesNotExist:
        return HttpResponseBadRequest()
    if not user.profile.totp:
        return HttpResponseBadRequest()
    totp = pyotp.totp.TOTP(user.profile.totp)
    if request.method == "POST":
        if not TokenBucket.authorize_totp_attempt(user):
            return render(request, "try_later.html")
        form = forms.TotpForm(totp, request.POST)
        if form.is_valid():
            if not TokenBucket.authorize_totp_code(user, form.cleaned_data["code"]):
                return render(request, "try_later.html")
            request.session.pop("2fa_user")
            auth_login(request, user, "hc.accounts.backends.EmailBackend")
            return _redirect_after_login(request)
    else:
        form = forms.TotpForm(totp)
    return render(request, "accounts/login_totp.html", {"form": form})
class Check(models.Model):
    code = models.UUIDField(default=uuid.uuid4, editable=False, unique=True)
    kind = models.CharField(max_length=10, default="simple", choices=CHECK_KINDS)
    def get_grace_start(self, *, with_started: bool = True) -> datetime | None:
        """Return the datetime when the grace period starts.
        If the check is currently new, paused or down, return None.
        """
        result = NEVER
        if self.kind == "simple" and self.status == "up":
            assert self.last_ping is not None
            result = self.last_ping + self.timeout
        elif self.kind == "cron" and self.status == "up":
            assert self.last_ping is not None
            last_local = self.last_ping.astimezone(ZoneInfo(self.tz))
            result = next(CronSim(self.schedule, last_local))
        if with_started and self.last_start and self.status != "down":
            result = min(result, self.last_start)
        return result if result != NEVER else None
    def get_status(self, *, with_started: bool = False) -> str:
        """Return current status for display."""
        frozen_now = now()
        if self.last_start:
            if frozen_now >= self.last_start + self.grace:
                return "down"
            elif with_started:
                return "started"
        if self.status in ("new", "paused", "down"):
            return self.status
        grace_start = self.get_grace_start(with_started=False)
        assert grace_start is not None
        grace_end = grace_start + self.grace
        if frozen_now >= grace_end:
            return "down"
        if frozen_now >= grace_start:
            return "grace"
        return "up"
    def to_dict(self, *, readonly: bool = False, v: int = 2) -> CheckDict:
        with_started = v == 1
        result: CheckDict = {
            "name": self.name,
            "slug": self.slug,
            "tags": self.tags,
            "desc": self.desc,
            "grace": int(self.grace.total_seconds()),
            "n_pings": self.n_pings,
            "status": self.get_status(with_started=with_started),
            "started": self.last_start is not None,
            "last_ping": isostring(self.last_ping),
            "next_ping": isostring(self.get_grace_start()),
            "manual_resume": self.manual_resume,
            "methods": self.methods,
            "subject": self.success_kw if self.filter_subject else "",
            "subject_fail": self.failure_kw if self.filter_subject else "",
            "start_kw": self.start_kw,
            "success_kw": self.success_kw,
            "failure_kw": self.failure_kw,
            "filter_subject": self.filter_subject,
            "filter_body": self.filter_body,
        }
        if self.last_duration:
            result["last_duration"] = int(self.last_duration.total_seconds())
        if readonly:
            result["unique_key"] = self.unique_key
        else:
            result["ping_url"] = settings.PING_ENDPOINT + str(self.code)
            update_url = settings.SITE_ROOT + f"/api/v{v}/checks/{self.code}"
            result["update_url"] = update_url
            result["pause_url"] = update_url + "/pause"
            result["resume_url"] = update_url + "/resume"
            result["channels"] = self.channels_str()
        if self.kind == "simple":
            result["timeout"] = int(self.timeout.total_seconds())
        elif self.kind == "cron":
            result["schedule"] = self.schedule
            result["tz"] = self.tz
        return result
    def ping(
        self,
        remote_addr: str,
        scheme: str,
        method: str,
        ua: str,
        body: bytes,
        action: str,
        rid: uuid.UUID | None,
        exitstatus: int | None = None,
    ) -> None:
        frozen_now = now()
        if self.status == "paused" and self.manual_resume:
            action = "ign"
        if action == "start":
            self.last_start = frozen_now
            self.last_start_rid = rid
        elif action == "ign":
            pass
        elif action == "log":
            pass
        else:
            self.last_ping = frozen_now
            self.last_duration = None
            if self.last_start:
                if self.last_start_rid == rid:
                    self.last_duration = self.last_ping - self.last_start
                    self.last_start = None
                elif action == "fail" or rid is None:
                    self.last_start = None
            new_status = "down" if action == "fail" else "up"
            if self.status != new_status:
                self.create_flip(new_status)
                self.status = new_status
        self.alert_after = self.going_down_after()
        self.n_pings = models.F("n_pings") + 1
        self.has_confirmation_link = "confirm" in body.decode(errors="replace").lower()
        self.save()
        self.refresh_from_db()
        ping = Ping(owner=self)
        ping.n = self.n_pings
        ping.created = frozen_now
        if action in ("start", "fail", "ign", "log"):
            ping.kind = action
        ping.remote_addr = remote_addr
        ping.scheme = scheme
        ping.method = method
        ping.ua = ua[:200]
        if len(body) > 100 and settings.S3_BUCKET:
            ping.object_size = len(body)
            put_object(self.code, ping.n, body)
        else:
            ping.body_raw = body
        ping.rid = rid
        ping.exitstatus = exitstatus
        ping.save()
        if self.n_pings % 100 == 0:
            self.prune()
    def downtimes_by_boundary(self, boundaries: list[datetime]):
        """Calculate downtime counts and durations for the given time intervals.
        Returns a list of (datetime, downtime_in_secs, number_of_outages) tuples
        in ascending datetime order.
        `boundaries` are the datetimes of the first days of time intervals
        (months or weeks) we're interested in, in ascending order.
        """
        summary = DowntimeSummary(boundaries)
        events = [(b, "---") for b in boundaries]
        q = self.flip_set.filter(created__gt=min(boundaries))
        for pair in q.values_list("created", "old_status"):
            events.append(pair)
        dt, status = now(), self.status
        for prev_dt, prev_status in sorted(events, reverse=True):
            if status == "down":
                summary.add(prev_dt, dt - prev_dt)
            dt = prev_dt
            if prev_status != "---":
                status = prev_status
        prev_boundary = None
        result: list[tuple[datetime, td | None, int | None]] = []
        for triple in summary.as_tuples():
            if prev_boundary and self.created > prev_boundary:
                result.append((triple[0], None, None))
                continue
            prev_boundary = triple[0]
            result.append(triple)
        result.sort()
        return result
class Ping(models.Model):
    def get_body_bytes(self) -> bytes | None:
        if self.body:
            return self.body.encode()
        if self.object_size:
            return get_object(self.owner.code, self.n)
        if self.body_raw:
            return self.body_raw
        return None
class Channel(models.Model):
    value = models.TextField(blank=True)
    def notify(self, check, is_test=False):
        if self.transport.is_noop(check):
            return "no-op"
        n = Notification(channel=self)
        if is_test:
            pass
        else:
            n.owner = check
        n.check_status = check.status
        n.error = "Sending"
        n.save()
        error, disabled = "", self.disabled
        try:
            self.transport.notify(check, notification=n)
        except transports.TransportError as e:
            disabled = True if e.permanent else disabled
            error = e.message
        Notification.objects.filter(id=n.id).update(error=error)
        Channel.objects.filter(id=self.id).update(
            last_notify=now(), last_error=error, disabled=disabled
        )
        return error
class Flip(models.Model):
    def send_alerts(self):
        """Loop over the enabled channels, call notify() on each.
        For each channel, yield a (channel, error, send_time) triple:
         * channel is a Channel instance
         * error is an empty string ("") on success, error message otherwise
         * send_time is specified in seconds (float)
        """
        if self.new_status == "up" and self.old_status in ("new", "paused"):
            return
        if self.new_status not in ("up", "down"):
            raise NotImplementedError("Unexpected status: %s" % self.status)
        for channel in self.owner.channel_set.exclude(disabled=True):
            start = time.time()
            error = channel.notify(self.owner)
            if error == "no-op":
                continue
            yield channel, error, time.time() - start
def _get_check_for_user(
    request: HttpRequest, code: UUID, preload_owner_profile: bool = False
) -> tuple[Check, bool]:
    """Return specified check if current user has access to it.
    If `preload_owner_profile` is `True`, the returned check's
    project.owner.profile will be already loaded. This helps avoid extra SQL queries
    if the caller later looks up the project owner's check_limit or ping_log_limit.
    """
    assert request.user.is_authenticated
    q = Check.objects.select_related("project")
    if preload_owner_profile:
        q = q.select_related("project__owner__profile")
    check = get_object_or_404(q, code=code)
    if request.user.is_superuser:
        return check, True
    if request.user.id == check.project.owner_id:
        return check, True
    membership = get_object_or_404(Member, project=check.project, user=request.user)
    return check, membership.is_rw
def _get_rw_check_for_user(request: HttpRequest, code: UUID) -> Check:
    check, rw = _get_check_for_user(request, code)
    if not rw:
        raise PermissionDenied
    return check
def _get_rw_channel_for_user(request: HttpRequest, code: UUID) -> Channel:
    channel, rw = _get_channel_for_user(request, code)
    if not rw:
        raise PermissionDenied
    return channel
def _get_project_for_user(request: HttpRequest, code: UUID) -> tuple[Project, bool]:
    """Check access, return (project, rw) tuple."""
    project = get_object_or_404(Project, code=code)
    if request.user.is_superuser:
        return project, True
    if request.user.id == project.owner_id:
        return project, True
    membership = get_object_or_404(Member, project=project, user=request.user)
    return project, membership.is_rw
def _get_rw_project_for_user(request: HttpRequest, code: UUID) -> Project:
