class DatasetDownloadHandler:
    def process_dowload(self, resource=None):
        """
        Generate the response object
        """
        if not resource:
            resource = self.get_resource()
        if not settings.USE_GEOSERVER:
            return HttpResponseRedirect(reverse("download", args=[resource.id]))
        download_format = self.request.GET.get("export_format")
        if download_format and not wps_format_is_supported(download_format, resource.subtype):
            logger.error("The format provided is not valid for the selected resource")
            return JsonResponse({"error": "The format provided is not valid for the selected resource"}, status=500)
        _format = "application/zip" if resource.is_vector() else "image/tiff"
        tpl = get_template("geoserver/dataset_download.xml")
        ctx = {"alternate": resource.alternate, "download_format": download_format or _format}
        payload = tpl.render(ctx)
        client = HttpClient()
        headers = {"Content-type": "application/xml", "Accept": "application/xml"}
        url = f"{settings.OGC_SERVER['default']['LOCATION']}ows?service=WPS&version=1.0.0&REQUEST=Execute"
        if not self.request.user.is_anonymous:
            access_token = get_or_create_token(self.request.user)
            url += f"&access_token={access_token}"
        response, content = client.request(url=url, data=payload, method="post", headers=headers)
        if not response or response.status_code != 200:
            logger.error(f"Download dataset exception: error during call with GeoServer: {content}")
            return JsonResponse(
                {"error": "Download dataset exception: error during call with GeoServer"},
                status=500,
            )
        namespaces = {"ows": "http://www.opengis.net/ows/1.1", "wps": "http://www.opengis.net/wps/1.0.0"}
        response_type = response.headers.get("Content-Type")
        if response_type == "text/xml":
            content = ET.fromstring(response.text)
            exc = content.find("*//ows:Exception", namespaces=namespaces) or content.find(
                "ows:Exception", namespaces=namespaces
            )
            if exc:
                exc_text = exc.find("ows:ExceptionText", namespaces=namespaces)
                logger.error(f"{exc.attrib.get('exceptionCode')} {exc_text.text}")
                return JsonResponse({"error": f"{exc.attrib.get('exceptionCode')}: {exc_text.text}"}, status=500)
        return_response = fetch_response_headers(
            HttpResponse(content=response.content, status=response.status_code, content_type=download_format),
            response.headers,
        )
        return_response.headers["Content-Type"] = download_format or _format
        return return_response
def get_files(filename):
    """Converts the data to Shapefiles or Geotiffs and returns
    a dictionary with all the required files
    """
    files = {}
    try:
        filename.encode("ascii")
    except UnicodeEncodeError:
        msg = f"Please use only characters from the english alphabet for the filename. '{os.path.basename(filename).encode('UTF-8', 'strict')}' is not yet supported."
        raise GeoNodeException(msg)
    from geonode.utils import unzip_file, mkdtemp
    tempdir = None
    if is_zipfile(filename):
        tempdir = mkdtemp()
        _filename = unzip_file(filename, ".shp", tempdir=tempdir)
        if not _filename:
            import ntpath
            from geonode.upload.utils import _SUPPORTED_EXT
            file_basename, file_ext = ntpath.splitext(filename)
            for item in os.listdir(tempdir):
                item_basename, item_ext = ntpath.splitext(item)
                if ntpath.basename(item_basename) == ntpath.basename(file_basename) and (
                    item_ext.lower() in _SUPPORTED_EXT
                ):
                    filename = os.path.join(tempdir, item)
                    break
        else:
            filename = _filename
    if not os.path.exists(filename):
        msg = f"Could not open {filename}. Make sure you are using a valid file"
        logger.debug(msg)
        raise GeoNodeException(msg)
    base_name, extension = os.path.splitext(filename)
    glob_name = re.sub(r"([\[\]\(\)\{\}])", r"[\g<1>]", base_name)
    if extension.lower() == ".shp":
        required_extensions = dict(shp=".[sS][hH][pP]", dbf=".[dD][bB][fF]", shx=".[sS][hH][xX]")
        for ext, pattern in required_extensions.items():
            matches = glob.glob(glob_name + pattern)
            if len(matches) == 0:
                msg = (
                    f"Expected helper file {base_name}.{ext} does not exist; a Shapefile "
                    "requires helper files with the following extensions: "
                    f"{list(required_extensions.keys())}"
                )
                raise GeoNodeException(msg)
            elif len(matches) > 1:
                msg = (
                    "Multiple helper files for %s exist; they need to be " "distinct by spelling and not just case."
                ) % filename
                raise GeoNodeException(msg)
            else:
                files[ext] = matches[0]
        matches = glob.glob(f"{glob_name}.[pP][rR][jJ]")
        if len(matches) == 1:
            files["prj"] = matches[0]
        elif len(matches) > 1:
            msg = (
                "Multiple helper files for %s exist; they need to be " "distinct by spelling and not just case."
            ) % filename
            raise GeoNodeException(msg)
    elif extension.lower() in cov_exts:
        files[extension.lower().replace(".", "")] = filename
    if check_ogc_backend(geoserver.BACKEND_PACKAGE):
        matches = glob.glob(f"{os.path.dirname(glob_name)}.[sS][lL][dD]")
        if len(matches) == 1:
            files["sld"] = matches[0]
        else:
            matches = glob.glob(f"{glob_name}.[sS][lL][dD]")
            if len(matches) == 1:
                files["sld"] = matches[0]
            elif len(matches) > 1:
                msg = (
                    "Multiple style files (sld) for %s exist; they need to be "
                    "distinct by spelling and not just case."
                ) % filename
                raise GeoNodeException(msg)
    matches = glob.glob(f"{glob_name}.[xX][mM][lL]")
    if len(matches) == 0:
        matches = glob.glob(f"{filename}.[xX][mM][lL]")
    if len(matches) == 1:
        files["xml"] = matches[0]
    elif len(matches) > 1:
        msg = ("Multiple XML files for %s exist; they need to be " "distinct by spelling and not just case.") % filename
        raise GeoNodeException(msg)
    return files, tempdir
