    """
    Validate that the given node matches the expected type(s)
    Raises if the node does not match one of the expected types.
    Arguments
    ---------
    node : VyperNode
        Vyper ast node.
    expected_type : Tuple | BaseType
        A type object, or tuple of type objects
    Returns
    -------
    None
    """
