                      ua.NodeId(ua.ObjectIds.ActivateSessionRequest_Encoding_DefaultBinary),
                      ua.NodeId(ua.ObjectIds.FindServersRequest_Encoding_DefaultBinary),
                      ua.NodeId(ua.ObjectIds.GetEndpointsRequest_Encoding_DefaultBinary)]:
