class StatusPage(Controller):
    def _data(self, days):
        """
        Return number of backups per days including failure.
        """
        def _key(d):
            return time.strftime(str(d).split('T')[0])
        base = RdiffTime().set_time(0, 0, 0) - datetime.timedelta(days=days)
        data = {_key(base + datetime.timedelta(days=i)): [] for i in range(0, days + 1)}
        success = {_key(base + datetime.timedelta(days=i)): 0 for i in range(0, days + 1)}
        failure = success.copy()
        for repo in self.app.currentuser.repo_objs:
            if len(repo.session_statistics):
                for stat in repo.session_statistics[base:]:
                    key = _key(stat.date)
                    if key not in success:
                        continue
                    success[key] = success.get(key, 0) + 1
                    data[key].append(stat)
                    if stat.errors:
                        failure[key] += 1
        return {
            'backup_count': [
                {'name': _('Successful Backup'), 'data': success},
                {'name': _('Backup with errors'), 'data': failure},
            ],
            'data': data,
        }
def hash_password(password):
    assert password and isinstance(password, str)
    password = password.encode(encoding='utf8')
    salt = os.urandom(4)
    h = hashlib.sha1(password)
    h.update(salt)
    return "{SSHA}" + b64encode(h.digest() + salt).decode('latin1')
def check_password(password, challenge):
    """
    Check if the password matches the challenge.
    The challenge is an encrypted password.
    """
    if not password or not challenge:
        return False
    assert isinstance(password, str)
    assert isinstance(challenge, str)
    if challenge.startswith('{SSHA}'):
        digest_salt = b64decode(challenge[6:])
        digest = digest_salt[:20]
        sha = hashlib.sha1(password.encode(encoding='utf8'))
        sha.update(digest_salt[20:])
        return digest == sha.digest()
    else:
        sha = hashlib.sha1(password.encode('utf8'))
        return challenge == sha.hexdigest()
