class SlskMessage:
    def pack_object(self, obj, signedint=False, unsignedlonglong=False, latin1=False):
        """ Returns object (integer, long or string packed into a
        binary array."""
        if isinstance(obj, int):
            if signedint:
                return INT_PACK(obj)
            if unsignedlonglong:
                return UINT64_PACK(obj)
            return UINT_PACK(obj)
        if isinstance(obj, bytes):
            return UINT_PACK(len(obj)) + obj
        if isinstance(obj, str):
            if latin1:
                try:
                    encoded = bytes(obj, "latin-1")
                except Exception:
                    encoded = bytes(obj, "utf-8", "replace")
            else:
                encoded = bytes(obj, "utf-8", "replace")
            return UINT_PACK(len(encoded)) + encoded
        log.add("Warning: unknown object type %(obj_type)s in message %(msg_type)s",
                {'obj_type': type(obj), 'msg_type': self.__class__})
        return b""
class RoomList(ServerMessage):
    def get_rooms(self, originalpos, message):
        try:
            pos, numrooms = self.get_object(message, int, originalpos)
            rooms = []
            for i in range(numrooms):
                pos, room = self.get_object(message, str, pos)
                rooms.append([room, None])
            pos, numusers = self.get_object(message, int, pos)
            for i in range(numusers):
                pos, usercount = self.get_object(message, int, pos)
                rooms[i][1] = usercount
            return (pos, rooms)
        except Exception as error:
            log.add("Exception during parsing %(area)s: %(exception)s", {'area': 'RoomList', 'exception': error})
            return (originalpos, [])
class ChatEntry:
    def on_enter(self, *_args):
        if not self.frame.np.logged_in:
            return
        text = self.entry.get_text()
        if not text:
            return
        if is_alias(text):
            alias_text = get_alias(text)
            if not alias_text:
                log.add(_('Alias "%s" returned nothing'), text)
                return
            text = alias_text
        is_double_slash_cmd = text.startswith("//")
        is_single_slash_cmd = (text.startswith("/") and not is_double_slash_cmd)
        if not is_single_slash_cmd or text.startswith("/me"):
            self.entry.set_text("")
            if is_double_slash_cmd:
                text = text[1:]
            self.send_message(self.entity, text)
            return
        cmd_split = text.split(maxsplit=1)
        cmd = cmd_split[0]
        if cmd + " " not in self.command_list:
            log.add(_("Command %s is not recognized"), cmd)
            return
        self.entry.set_text("")
        if len(cmd_split) == 2:
            args = arg_self = cmd_split[1]
        else:
            args = ""
            arg_self = "" if self.is_chatroom else self.entity
        if cmd in ("/alias", "/al"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, add_alias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/unalias", "/un"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, unalias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/w", "/whois", "/info"):
            if arg_self:
                self.frame.np.userinfo.request_user_info(arg_self)
                self.frame.change_main_page("userinfo")
        elif cmd in ("/b", "/browse"):
            if arg_self:
                self.frame.np.userbrowse.browse_user(arg_self)
                self.frame.change_main_page("userbrowse")
        elif cmd == "/ip":
            if arg_self:
                self.frame.np.request_ip_address(arg_self)
        elif cmd == "/pm":
            if args:
                self.frame.np.privatechats.show_user(args)
                self.frame.change_main_page("private")
        elif cmd in ("/m", "/msg"):
