class UPnPPortMapping:
    def add_port_mapping(self, router, protocol, public_port, private_ip, private_port,
                         mapping_description, lease_duration):
        """
        Function that adds a port mapping to the router.
        If a port mapping already exists, it is updated with a lease period of 24 hours.
        """
        from xml.etree import ElementTree
        url = '%s%s' % (router.base_url, router.control_url)
        log.add_debug("UPnP: Adding port mapping (%s %s/%s, %s) at url '%s'",
                      (private_ip, private_port, protocol, router.search_target, url))
        headers = {
            "Host": router.base_url,
            "Content-Type": "text/xml; charset=utf-8",
            "SOAPACTION": '"%s
        }
        body = (self.request_body % (router.service_type, public_port, protocol, private_port, private_ip,
                                     mapping_description, lease_duration)).encode('utf-8')
        log.add_debug("UPnP: Add port mapping request headers: %s", headers)
        log.add_debug("UPnP: Add port mapping request contents: %s", body)
        response = http_request(
            router.url_scheme, router.base_url, router.control_url,
            request_type="POST", body=body, headers=headers)
        xml = ElementTree.fromstring(response)
        if not xml.find(".//{http://schemas.xmlsoap.org/soap/envelope/}Body"):
            raise Exception("Invalid port mapping response: %s" % response.encode('utf-8'))
        log.add_debug("UPnP: Add port mapping response: %s", response.encode('utf-8'))
        error_code = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorCode")
        error_description = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorDescription")
        if error_code or error_description:
            raise Exception("Error code %(code)s: %(description)s" %
                            {"code": error_code, "description": error_description})
class Search:
    def process_search_request(self, searchterm, user, searchid, direct=False):
        """ Note: since this section is accessed every time a search request arrives,
        several times a second, please keep it as optimized and memory
        sparse as possible! """
        if not searchterm:
            return
        if not self.config.sections["searches"]["search_results"]:
            return
        if not direct and user == self.config.sections["server"]["login"]:
            return
        maxresults = self.config.sections["searches"]["maxresults"]
        if maxresults == 0:
            return
        excluded_words = []
        partial_words = []
        if '-' in searchterm or '*' in searchterm:
            for word in searchterm.split():
                if len(word) < 1:
                    continue
                if word.startswith('-'):
                    for subword in word.translate(self.translatepunctuation).split():
                        excluded_words.append(subword)
                elif word.startswith('*'):
                    for subword in word.translate(self.translatepunctuation).split():
                        partial_words.append(subword)
        searchterm_old = searchterm
        searchterm = searchterm.lower().translate(self.translatepunctuation).strip()
        if len(searchterm) < self.config.sections["searches"]["min_search_chars"]:
            return
        checkuser, _reason = self.core.network_filter.check_user(user, None)
        if not checkuser:
            return
        if checkuser == 2:
            wordindex = self.share_dbs.get("buddywordindex")
        else:
            wordindex = self.share_dbs.get("wordindex")
        if wordindex is None:
            return
        resultlist = self.create_search_result_list(searchterm, wordindex, excluded_words, partial_words)
        if not resultlist:
            return
        if checkuser == 2:
            fileindex = self.share_dbs.get("buddyfileindex")
        else:
            fileindex = self.share_dbs.get("fileindex")
        if fileindex is None:
            return
        fileinfos = []
        numresults = min(len(resultlist), maxresults)
        for index in islice(resultlist, numresults):
            fileinfo = fileindex.get(repr(index))
            if fileinfo is not None:
                fileinfos.append(fileinfo)
        if numresults != len(fileinfos):
            log.add_debug(("File index inconsistency while responding to search request "
                           "\"%(query)s\". %(expected_num)s results expected, but only %(total_num)s "
                           "results were found in database."), {
                "query": searchterm_old,
                "expected_num": numresults,
                "total_num": len(fileinfos)
            })
        numresults = len(fileinfos)
        if not numresults:
            return
        uploadspeed = self.core.transfers.upload_speed
        queuesize = self.core.transfers.get_upload_queue_size()
        slotsavail = self.core.transfers.allow_new_uploads()
        fifoqueue = self.config.sections["transfers"]["fifoqueue"]
        message = slskmessages.FileSearchResult(
            None, self.config.sections["server"]["login"],
            searchid, fileinfos, slotsavail, uploadspeed, queuesize, fifoqueue)
        self.core.send_message_to_peer(user, message)
        if direct:
            log.add_search(
                _("User %(user)s is directly searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
        else:
            log.add_search(
                _("User %(user)s is searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
class Notifications:
    def new_text_notification(self, message, title=None, priority=Gio.NotificationPriority.NORMAL):
        if title is None:
            title = config.application_name
        try:
            if sys.platform == "win32":
                self.win_notification.notify(
                    title=title,
                    message=message
                )
                if config.sections["notifications"]["notification_popup_sound"]:
                    import winsound
