class ComponentRequest:
    def __init__(self, request, component_name):
        self.body = {}
        self.request = request
        try:
            self.body = loads(request.body)
            assert self.body, "Invalid JSON body"
        except JSONDecodeError as e:
            raise UnicornViewError("Body could not be parsed") from e
        self.name = component_name
        assert self.name, "Missing component name"
        self.data = self.body.get("data")
        assert self.data is not None, "Missing data"
        self.id = self.body.get("id")
        assert self.id, "Missing component id"
        self.epoch = self.body.get("epoch", "")
        assert self.epoch, "Missing epoch"
        self.key = self.body.get("key", "")
        self.hash = self.body.get("hash", "")
        self.validate_checksum()
        self.action_queue = []
        for action_data in self.body.get("actionQueue", []):
            self.action_queue.append(Action(action_data))
    def validate_checksum(self):
        """
        Validates that the checksum in the request matches the data.
        Returns:
            Raises `AssertionError` if the checksums don't match.
        """
        checksum = self.body.get("checksum")
        assert checksum, "Missing checksum"
        generated_checksum = generate_checksum(dumps(self.data, fix_floats=False))
        assert checksum == generated_checksum, "Checksum does not match"
class Return:
    def get_data(self):
        try:
            serialized_value = loads(dumps(self.value))
            serialized_args = loads(dumps(self.args))
            serialized_kwargs = loads(dumps(self.kwargs))
            return {
                "method": self.method_name,
                "args": serialized_args,
                "kwargs": serialized_kwargs,
                "value": serialized_value,
            }
        except Exception as e:
            logger.exception(e)
        return {}
def convert_to_snake_case(s: str) -> str:
    return s.replace("-", "_")
def convert_to_pascal_case(s: str) -> str:
    s = convert_to_snake_case(s)
    return "".join(word.title() for word in s.split("_"))
def get_locations(component_name):
    locations = []
    if "." in component_name:
        component_name = component_name.replace("/", ".")
        class_name = component_name.split(".")[-1:][0]
        module_name = component_name.replace("." + class_name, "")
        locations.append((class_name, module_name))
        if component_name.endswith("View") or component_name.endswith("Component"):
            return locations
    component_name = component_name.replace("/", ".")
    class_name = convert_to_pascal_case(component_name)
    if "." in class_name:
        if class_name.split(".")[-1:]:
            class_name = class_name.split(".")[-1:][0]
    class_name = f"{class_name}View"
    module_name = convert_to_snake_case(component_name)
    unicorn_apps = get_setting("APPS", settings.INSTALLED_APPS)
    assert (
        isinstance(unicorn_apps, list)
        or isinstance(unicorn_apps, tuple)
        or isinstance(unicorn_apps, set)
    ), "APPS is expected to be a list, tuple or set"
    for app in unicorn_apps:
        if ".apps." in app:
            app_config_idx = app.rindex(".apps.")
            app = app[:app_config_idx]
        app_module_name = f"{app}.components.{module_name}"
        locations.append((class_name, app_module_name))
    return locations
@timed
def construct_component(
    component_class,
    component_id,
    component_name,
    component_key,
    parent,
    request,
    **kwargs,
):
    """
    Constructs a class instance.
    """
    component = component_class(
        component_id=component_id,
        component_name=component_name,
        component_key=component_key,
        parent=parent,
        request=request,
        **kwargs,
    )
    component.calls = []
    component.children = []
    component._children_set = False
    component.mount()
    component.hydrate()
    component.complete()
    component._validate_called = False
    return component
